/* ============================================================
   21_BandejaCatalogo.sql
   Catálogo de bandejas y su detalle de productos.

   Origen: exportación de las listas de SharePoint del formulario de
   Solicitud de Equipo (Bandeja.txt y bandejaDetalle.txt).

   Convive con lo que ya hay en cat.Equipo / cat.EquipoProducto: los
   registros que no existen se agregan y los que ya existen NO se
   sobrescriben — solo se completan los campos que estén en NULL.

   Convención de código, igual que la de los registros existentes
   (Codigo='10284', Demarcado='NUT-10284'):
     'NUT-0001330' -> Codigo='0001330', Demarcado='NUT-0001330'
     'BVO-031'     -> Codigo='BVO-031', Demarcado='BVO-031'

   Aplicar a mano con psql, antes del push.
   ============================================================ */

BEGIN;

/* ---------- 1. Columnas nuevas ---------- */

-- Categoría de la bandeja (Instrumental / Implantes).
ALTER TABLE cat.Equipo ADD COLUMN IF NOT EXISTS Categoria VARCHAR(60) NULL;

-- Bandeja completa (Sí/No). Se administra desde la pantalla de Bandejas.
ALTER TABLE cat.Equipo ADD COLUMN IF NOT EXISTS Completo BOOLEAN NOT NULL DEFAULT TRUE;

-- Motivo obligatorio cuando la bandeja se marca incompleta.
ALTER TABLE cat.Equipo ADD COLUMN IF NOT EXISTS MotivoIncompleto VARCHAR(300) NULL;

-- Cantidad de cada producto dentro de la bandeja.
ALTER TABLE cat.EquipoProducto ADD COLUMN IF NOT EXISTS Cantidad NUMERIC(10,2) NOT NULL DEFAULT 1;

-- Tipo de instrumento que viene del catálogo de SharePoint.
ALTER TABLE cat.EquipoProducto ADD COLUMN IF NOT EXISTS Tipo VARCHAR(40) NULL;

/* Descripción del producto al momento de la carga. La pantalla muestra la
   del catálogo de productos (/api/productos); esta queda como respaldo para
   cuando ese flujo no responda. */
ALTER TABLE cat.EquipoProducto ADD COLUMN IF NOT EXISTS DescripcionProducto VARCHAR(300) NULL;

ALTER TABLE cat.EquipoProducto ADD COLUMN IF NOT EXISTS ActualizadoPor VARCHAR(200) NULL;
ALTER TABLE cat.EquipoProducto ADD COLUMN IF NOT EXISTS FechaActualizacion TIMESTAMP(0) NULL;

/* La cantidad no puede ser negativa. Se permite el cero a proposito: nueve
   lineas del export de SharePoint vinieron sin cantidad registrada y se cargan
   tal cual, para no inventar un valor que despues nadie revisaria. Quedan
   listadas al final de este archivo y la pantalla las marca en amarillo.
   La API es mas estricta que la base: al agregar o editar un producto exige
   una cantidad mayor que cero, asi que no se pueden crear ceros nuevos. */
ALTER TABLE cat.EquipoProducto DROP CONSTRAINT IF EXISTS CK_EquipoProducto_Cantidad;
ALTER TABLE cat.EquipoProducto ADD  CONSTRAINT CK_EquipoProducto_Cantidad CHECK (Cantidad >= 0);


/* ---------- 2. Bandejas ---------- */

ON CONFLICT (Codigo) DO UPDATE SET
     -- No se sobrescribe lo que ya estaba: solo se rellena lo que está en NULL.
     Demarcado = COALESCE(cat.Equipo.Demarcado, EXCLUDED.Demarcado),
     Nombre    = COALESCE(cat.Equipo.Nombre,    EXCLUDED.Nombre),
     Categoria = COALESCE(cat.Equipo.Categoria, EXCLUDED.Categoria),
     Color     = COALESCE(cat.Equipo.Color,     EXCLUDED.Color);


/* ---------- 3. Detalle de productos ---------- */

ON CONFLICT (EquipoCodigo, ProductoCodigo) DO UPDATE SET
     Cantidad            = EXCLUDED.Cantidad,
     Tipo                = COALESCE(cat.EquipoProducto.Tipo, EXCLUDED.Tipo),
     DescripcionProducto = COALESCE(cat.EquipoProducto.DescripcionProducto, EXCLUDED.DescripcionProducto),
     ActualizadoPor      = EXCLUDED.ActualizadoPor,
     FechaActualizacion  = EXCLUDED.FechaActualizacion;

ON CONFLICT (EquipoCodigo, ProductoCodigo) DO UPDATE SET
     Cantidad            = EXCLUDED.Cantidad,
     Tipo                = COALESCE(cat.EquipoProducto.Tipo, EXCLUDED.Tipo),
     DescripcionProducto = COALESCE(cat.EquipoProducto.DescripcionProducto, EXCLUDED.DescripcionProducto),
     ActualizadoPor      = EXCLUDED.ActualizadoPor,
     FechaActualizacion  = EXCLUDED.FechaActualizacion;

ON CONFLICT (EquipoCodigo, ProductoCodigo) DO UPDATE SET
     Cantidad            = EXCLUDED.Cantidad,
     Tipo                = COALESCE(cat.EquipoProducto.Tipo, EXCLUDED.Tipo),
     DescripcionProducto = COALESCE(cat.EquipoProducto.DescripcionProducto, EXCLUDED.DescripcionProducto),
     ActualizadoPor      = EXCLUDED.ActualizadoPor,
     FechaActualizacion  = EXCLUDED.FechaActualizacion;

ON CONFLICT (EquipoCodigo, ProductoCodigo) DO UPDATE SET
     Cantidad            = EXCLUDED.Cantidad,
     Tipo                = COALESCE(cat.EquipoProducto.Tipo, EXCLUDED.Tipo),
     DescripcionProducto = COALESCE(cat.EquipoProducto.DescripcionProducto, EXCLUDED.DescripcionProducto),
     ActualizadoPor      = EXCLUDED.ActualizadoPor,
     FechaActualizacion  = EXCLUDED.FechaActualizacion;

ON CONFLICT (EquipoCodigo, ProductoCodigo) DO UPDATE SET
     Cantidad            = EXCLUDED.Cantidad,
     Tipo                = COALESCE(cat.EquipoProducto.Tipo, EXCLUDED.Tipo),
     DescripcionProducto = COALESCE(cat.EquipoProducto.DescripcionProducto, EXCLUDED.DescripcionProducto),
     ActualizadoPor      = EXCLUDED.ActualizadoPor,
     FechaActualizacion  = EXCLUDED.FechaActualizacion;

ON CONFLICT (EquipoCodigo, ProductoCodigo) DO UPDATE SET
     Cantidad            = EXCLUDED.Cantidad,
     Tipo                = COALESCE(cat.EquipoProducto.Tipo, EXCLUDED.Tipo),
     DescripcionProducto = COALESCE(cat.EquipoProducto.DescripcionProducto, EXCLUDED.DescripcionProducto),
     ActualizadoPor      = EXCLUDED.ActualizadoPor,
     FechaActualizacion  = EXCLUDED.FechaActualizacion;

ON CONFLICT (EquipoCodigo, ProductoCodigo) DO UPDATE SET
     Cantidad            = EXCLUDED.Cantidad,
     Tipo                = COALESCE(cat.EquipoProducto.Tipo, EXCLUDED.Tipo),
     DescripcionProducto = COALESCE(cat.EquipoProducto.DescripcionProducto, EXCLUDED.DescripcionProducto),
     ActualizadoPor      = EXCLUDED.ActualizadoPor,
     FechaActualizacion  = EXCLUDED.FechaActualizacion;

ON CONFLICT (EquipoCodigo, ProductoCodigo) DO UPDATE SET
     Cantidad            = EXCLUDED.Cantidad,
     Tipo                = COALESCE(cat.EquipoProducto.Tipo, EXCLUDED.Tipo),
     DescripcionProducto = COALESCE(cat.EquipoProducto.DescripcionProducto, EXCLUDED.DescripcionProducto),
     ActualizadoPor      = EXCLUDED.ActualizadoPor,
     FechaActualizacion  = EXCLUDED.FechaActualizacion;

ON CONFLICT (EquipoCodigo, ProductoCodigo) DO UPDATE SET
     Cantidad            = EXCLUDED.Cantidad,
     Tipo                = COALESCE(cat.EquipoProducto.Tipo, EXCLUDED.Tipo),
     DescripcionProducto = COALESCE(cat.EquipoProducto.DescripcionProducto, EXCLUDED.DescripcionProducto),
     ActualizadoPor      = EXCLUDED.ActualizadoPor,
     FechaActualizacion  = EXCLUDED.FechaActualizacion;

ON CONFLICT (EquipoCodigo, ProductoCodigo) DO UPDATE SET
     Cantidad            = EXCLUDED.Cantidad,
     Tipo                = COALESCE(cat.EquipoProducto.Tipo, EXCLUDED.Tipo),
     DescripcionProducto = COALESCE(cat.EquipoProducto.DescripcionProducto, EXCLUDED.DescripcionProducto),
     ActualizadoPor      = EXCLUDED.ActualizadoPor,
     FechaActualizacion  = EXCLUDED.FechaActualizacion;


/* ---------- 4. Revisión posterior ----------

   Pendientes que la carga NO resuelve y hay que ver a mano:

     - Código duplicado en el maestro: BATERIA (IDs SharePoint 42 y 43, «Juego de dos Baterías para taladro.»).
       Se cargó una sola vez. Si son dos bandejas físicas, la segunda se agrega
       desde la pantalla con un código propio.
     - Bandejas sin color de demarcación: CONS METRO, KIT KW, NUT- BATERIA, NUT-0001401.
     - Bandejas sin ningún producto: CONS METRO, NUT- BATERIA, NUT-0001401, NUT-10290.
     - Líneas que vinieron con cantidad CERO (9). Se cargaron en cero a
       propósito; hay que registrar la cantidad real desde la pantalla:
         0001331    236160         Protector, Φ 3.2mm
         0001332    236160         Protector, Φ 3.2mm
         0001332    31409000       Washer 4.0
         0001339    30387040       Tornillo Cortical, Rosca Completa, Autoperforante, 3.5, 3.5x
         0001344    24291114       Placa Dis Dor Húmero Bloq Compr 2.7/3.5, 6+14-Orif
         0001400    24278202       Placa Dis Radio Dos-Col Volar I, 2.4/2.7, 7+2-Orif
         0001403    24258112       Placa AnteroLat Clavicular Bloq Compr, 2.7/3.5, 7+5-Orif
         0001404    24257107       Placa Reconstrucción Clavicular Bloq Compr 3.5, 7-Orif
         0001410    24261208       Placa Lat Dis Fibula Bloq Compr 2.7/3.5, 5+3-Orif
*/

COMMIT;
